export function OfflineState({
  message = "{{message}}",
  accent = "{{accent}}",
  force = {{force}},
  radius = {{radius}},
}) {
  return (
    <div style={{ width: 300, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12 }}>
      <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, color: force ? accent : "#241430888", marginBottom: 10 }}>
        <span style={{ width: 8, height: 8, borderRadius: "50%", background: force ? accent : "#A8E6C1" }} />
        {force ? "Offline" : "Online"}
      </div>
      {force && (
        <div role="status" style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 12px", borderRadius: radius, background: `color-mix(in srgb, ${accent} 12%, #FAF7F2)`, color: accent, fontWeight: 600, fontSize: 12 }}>
          <svg width="16" height="16" viewBox="0 0 24 24" aria-hidden="true"><path d="m3 3 18 18M8.5 8.5A9 9 0 0 0 3.6 11M12 19h.01M16.5 13a9 9 0 0 1 2 1.4M20.4 11a9 9 0 0 0-2-1.6M6 15a9 9 0 0 1 3.3-2.1" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>
          <span>{message}</span>
        </div>
      )}
    </div>
  );
}
